using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 StyleBoxFlat Style(Color bg,Color border,int thickness=1,int pad=10){var s=new StyleBoxFlat{BgColor=bg,BorderColor=border,CornerRadiusTopLeft=3,CornerRadiusTopRight=3,CornerRadiusBottomLeft=3,CornerRadiusBottomRight=3,ContentMarginLeft=pad,ContentMarginRight=pad,ContentMarginTop=pad,ContentMarginBottom=pad};s.SetBorderWidthAll(thickness);return s;}
 void InitTheme(){comicTheme=new Theme{DefaultFontSize=15};comicTheme.DefaultFont=new SystemFont{FontNames=new[]{"Bahnschrift","Segoe UI"}};comicTheme.SetColor("font_color","Label",new Color(.88f,.85f,.73f));comicTheme.SetColor("font_color","Button",new Color(.90f,.86f,.73f));comicTheme.SetStylebox("normal","Button",Style(new Color(.13f,.17f,.17f),new Color(.26f,.31f,.28f),1,11));comicTheme.SetStylebox("hover","Button",Style(new Color(.22f,.27f,.23f),new Color(.68f,.57f,.34f),2,11));comicTheme.SetStylebox("pressed","Button",Style(new Color(.29f,.30f,.21f),new Color(.80f,.67f,.40f),2,11));comicTheme.SetStylebox("focus","Button",Style(new Color(0,0,0,0),new Color(.67f,.58f,.37f),1,11));comicTheme.SetStylebox("panel","PanelContainer",Style(new Color(.055f,.075f,.078f,.97f),new Color(.53f,.45f,.30f),2,8));comicTheme.SetStylebox("background","ProgressBar",Style(new Color(.11f,.14f,.13f),new Color(.04f,.05f,.05f),1,0));comicTheme.SetStylebox("fill","ProgressBar",Style(new Color(.53f,.60f,.35f),new Color(.53f,.60f,.35f),0,0));comicTheme.SetStylebox("panel","LineEdit",Style(new Color(.09f,.12f,.12f),new Color(.35f,.39f,.32f),1,8));}
 Label HudLabel(int font=15){var l=new Label{MouseFilter=Control.MouseFilterEnum.Ignore};l.AddThemeFontSizeOverride("font_size",font);l.AddThemeColorOverride("font_shadow_color",new Color(.02f,.03f,.03f));l.AddThemeConstantOverride("shadow_offset_x",2);l.AddThemeConstantOverride("shadow_offset_y",2);hudRoot.AddChild(l);return l;}
 void NewHud(){InitTheme();ui=new CanvasLayer();AddChild(ui);hudRoot=new Control{MouseFilter=Control.MouseFilterEnum.Ignore,Theme=comicTheme};hudRoot.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);ui.AddChild(hudRoot);zoneLabel=HudLabel(22);clockLabel=HudLabel(14);hpLabel=HudLabel(14);needsLabel=HudLabel(13);ammoLabel=HudLabel(22);woundLabel=HudLabel(15);promptLabel=HudLabel(15);helpLabel=HudLabel(12);notice=HudLabel(14);hud=zoneLabel;hpBar=new ProgressBar{ShowPercentage=false,MouseFilter=Control.MouseFilterEnum.Ignore};staminaBar=new ProgressBar{ShowPercentage=false,MouseFilter=Control.MouseFilterEnum.Ignore};hudRoot.AddChild(hpBar);hudRoot.AddChild(staminaBar);damageTint=new ColorRect{Color=new Color(.55f,.1f,.05f,0),MouseFilter=Control.MouseFilterEnum.Ignore};damageTint.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);hudRoot.AddChild(damageTint);var crosshair=new InkCrosshair{MouseFilter=Control.MouseFilterEnum.Ignore};crosshair.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);hudRoot.AddChild(crosshair);BuildHudFrame();}
 void ComicHud(){PolishedHud();}
 string InteractionPrompt(){if(game.World.Changes.ScavengeAlarm is ScavengeAlarm alarm&&Distance(player.Position,alarm.Position)<3)return "F / SILENCE NOISE SOURCE";if(NearProp(12,3)!=null)return "F / READ LUMBER MILL WARNING";if(NearProp(13,4)!=null)return game.World.Changes.MillDefeated?"LUMBER MILL / CLEARED":"F / RING BELL / CHALLENGE THE FOREMAN";if(mountedBlueprint!=null)return "WASD / DRIVE / F DISMOUNT";var station=NearBlueprint();if(!buildMode&&station!=null)return "F / "+station.Def.Name.ToUpperInvariant();if(buildMode)return BuildDefinition.All[selectedBuild].Name.ToUpper()+"  /  "+(placement==null?"Aim at a surface":placement.Reason);if(dungeon!=null){if(Distance(player.Position,new Vector3(0,0,3))<2)return "F  /  RETURN TO SURFACE";for(int i=0;i<3;i++)if(Distance(player.Position,new Vector3((float)ExpeditionDungeon.ChestX[i],0,(float)ExpeditionDungeon.ChestZ[i]))<2.5)return Guarded(ExpeditionDungeon.ChestX[i],ExpeditionDungeon.ChestZ[i],8)?"CHEST GUARDED  /  CLEAR INFECTED":"F  /  SEARCH RELIC CHEST";if(dungeon.Tier==4&&Distance(player.Position,new Vector3(0,0,-26))<2.2)return "F  /  DESCEND TO ISOLATION WARD";if(dungeon.Deep&&Distance(player.Position,new Vector3(5,0,-22))<2.4)return "F  /  RECOVER BIOALLOY";for(int i=0;i<3;i++)if(Distance(player.Position,dungeonRecords[i])<2.5)return "F  /  READ ABANDONED RECORD";return "";}foreach(var d in ExpeditionDungeon.Nearby(game.World,0,0))if(Distance(player.Position,Ground(d.X,d.Z))<3.5)return "F  /  ENTER "+d.Name;foreach(var well in game.World.Changes.Wells)if(ExpeditionGame.Distance(player.Position.X,player.Position.Z,well.X,well.Z)<2.3)return "F  /  DRAW WATER";if(NearProp(10,2.8f)!=null)return "F  /  OPEN WORKTABLE";if(NearProp(9,2.6f)!=null)return "F  /  SEARCH SUPPLIES";var resource=NearProp(1,3);if(resource!=null)return "F  /  GATHER "+ExpeditionGame.ResourceNames[resource.Material].ToUpper();if(NearProp(0)!=null)return axeEquipped?"LEFT CLICK / AIM AT TRUNK / SWING":"T / EQUIP CHOPPING AXE";if(NearProp(2,4)!=null||NearProp(8,4)!=null)return "F  /  READ ABANDONED NOTE";return "";}
}
internal partial class InkCrosshair:Control {
 public override void _Draw(){var p=Size*.5f;foreach(var d in new[]{Vector2.Up,Vector2.Down,Vector2.Left,Vector2.Right}){DrawLine(p+d*4,p+d*10,new Color(.04f,.05f,.05f),3);DrawLine(p+d*4,p+d*9,new Color(.87f,.86f,.72f),1);}}
}
